javascript:
frappe.ready(() => {
    initializePaymentPage();
});


function initializePaymentPage() {

    const paymentToken =
        getPaymentToken();

    if (!paymentToken) {

        showPaymentError(
            "Invalid payment link."
        );

        return;
    }

    startRegistrationPayment(
        paymentToken
    );
}


function getPaymentToken() {

    const params =
        new URLSearchParams(
            window.location.search
        );

    return params.get("token");
}


function startRegistrationPayment(
    paymentToken
) {

    frappe.call({

        method:
            "registration_portal.registration_portal.api.start_registration_payment",

        args: {
            payment_token:
                paymentToken
        },

        callback(r) {

            console.log(
                "Payment response:",
                r.message
            );

            const result =
                r.message;

            if (!result) {

                showPaymentError(
                    "Unable to initialize payment."
                );

                return;
            }


            if (
                result.status === "paid"
            ) {

                showPaymentError(
                    "This registration has already been paid."
                );

                return;
            }


            if (
                result.payment_url
            ) {

                window.location.assign(
                    result.payment_url
                );

                return;
            }


            showPaymentError(
                "Unable to get the payment link."
            );
        },


        error(err) {

            console.error(
                "Payment initialization error:",
                err
            );

            showPaymentError(
                "Unable to connect to the payment service."
            );
        }

    });
}


function showPaymentError(
    message
) {

    const container =
        document.getElementById(
            "payment-container"
        );

    if (!container) {
        return;
    }

    container.innerHTML = `

        <div class="alert alert-danger">
            ${escapeHtml(message)}
        </div>

        <a
            href="/register"
            class="btn btn-primary"
        >
            Back to Registration
        </a>

    `;
}


function escapeHtml(value) {

    const div =
        document.createElement("div");

    div.textContent =
        value == null
            ? ""
            : String(value);

    return div.innerHTML;
}

